package san_receipt_readers

import (
	"math"
	"regexp"
	"strings"
)

// kiriminAjaLayout is a label printed by KiriminAja, a shipping aggregator: the seller books the
// courier through KiriminAja, and the label is KiriminAja's whichever courier carries it. Measured
// on one sample (kirimin_aja_id_express_01.pdf, ID Express), generated by wkhtmltopdf like TikTok's.
//
// Every value sits under its caption: "AWB" over the tracking number, "No. Trx KiriminAja" over
// KiriminAja's own booking number, "Penerima" over the recipient. The courier is printed ("ID
// Express Flat") and not read (courier-is-not-read). No logo gates the layout: the caption says which
// number is the tracking number, whichever courier it belongs to.
var kiriminAjaLayout = layout{
	name: "kiriminaja",
	match: func(v *pageView) bool {
		return readKiriminAjaTracking(v.rows) != ""
	},
	read: func(v *pageView) ReceiptData {
		// OrderID stays "": the label prints no marketplace order id. Its "No. Trx KiriminAja"
		// ("OID-…") is KiriminAja's booking number — Q11 in context_clarify.md.
		return ReceiptData{
			Receipt: readKiriminAjaTracking(v.rows),
		}.with(readKiriminAjaRecipient(v.rows))
	},
}

// kiriminAjaTracking is a tracking number under the "AWB" caption. KiriminAja books several
// couriers, each numbering its own way ("IDE7000000000001" for ID Express), so it is only checked
// to be one unbroken code.
var kiriminAjaTracking = regexp.MustCompile(`^[0-9A-Z]{8,24}$`)

// readKiriminAjaTracking is the word under "AWB" on the caption row that says "KiriminAja".
func readKiriminAjaTracking(rows []row) string {
	for i, r := range rows {
		if i+1 >= len(rows) || !strings.Contains(r.text(), "KiriminAja") {
			continue
		}

		value := under(r, rows[i+1], "AWB")
		if kiriminAjaTracking.MatchString(value) && strings.ContainsAny(value, "0123456789") {
			return value
		}
	}

	return ""
}

// A value starts within this fraction of its caption's size of where the caption starts.
const captionAlign = 0.5

// under is the word of `values` that starts where the caption word `caption` of `captions` starts,
// or "".
func under(captions, values row, caption string) string {
	for _, c := range captions.words {
		if c.s != caption {
			continue
		}
		for _, w := range values.words {
			if math.Abs(w.x0-c.x0) <= c.size*captionAlign {
				return w.s
			}
		}
	}

	return ""
}

// readKiriminAjaRecipient reads the two-column block under "Penerima" (left) and "Dari" (right, the
// sender): the name, the phone, then the address, each column left-aligned under its caption.
//
// Every row is cut where the "Dari" caption starts. The sender's address can share a row with the
// recipient's ("… RW. 05, Kec." | "Tangerang, Banten"), and the recipient's ends just short of it.
//
// This is the one label so far that prints the RECIPIENT's phone, in full.
func readKiriminAjaRecipient(rows []row) recipient {
	i := rowStartingWith(rows, "Penerima")
	if i < 0 || i+1 >= len(rows) {
		return recipient{}
	}

	head := rows[i]
	size := head.words[0].size
	limit := math.Inf(1)
	for _, w := range head.words {
		if w.s == "Dari" {
			limit = w.x0 - columnSlack
			break
		}
	}

	name := joinWords(rows[i+1].sized(size).leftOf(limit))

	next, phone := i+2, ""
	if next < len(rows) {
		words := rows[next].sized(size).leftOf(limit)
		if len(words) == 1 && barePhone.MatchString(words[0].s) {
			phone = words[0].s
			next++
		}
	}

	return recipient{
		name:    printed(name),
		phone:   printed(phone),
		address: addressBlock(rows[min(next, len(rows)):], size, math.Inf(-1), limit),
	}
}
